 library:'<path d="M4 4h4v16H4zM10 4h4v16h-4zM16 5l4-1 3 15-4 1z"/>',import:'<path d="M12 3v12m-4-4 4 4 4-4M5 20h14"/>',manifest:'<path d="M4 12h4l2-6 4 12 2-6h4"/><path d="M3 3h18v18H3z"/>',extract:'<path d="M4 5h16v14H4zM8 9h8m-8 4h5"/><path d="m15 15 2 2 4-5"/>',
 diagnostics:'<path d="M3 12h4l3-7 4 14 3-7h4"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l.6 2.6 2.3 1.3 2.5-.8 3 5.2-1.9 1.8v2.7l1.9 1.7-3 5.2-2.5-.7-2.3 1.3L15 25H9l-.6-2.7-2.3-1.3-2.5.7-3-5.2 1.9-1.7v-2.7L.6 10.3l3-5.2 2.5.8 2.3-1.3L9 3Z" transform="translate(2 0) scale(.83)"/>',
