 compare:'<path d="M3 7h16m-4-4 4 4-4 4M21 17H5m4-4-4 4 4 4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2"/>',moon:'<path d="M21 13a9 9 0 1 1-10-10 7 7 0 0 0 10 10Z"/>',monitor:'<rect x="3" y="3" width="18" height="14" rx="2"/><path d="M12 17v4m-5 0h10"/>',file:'<path d="M14 3H5v18h14V8l-5-5Z"/><path d="M14 3v5h5M8 12h8m-8 4h6"/>',grid:'<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>',list:'<path d="M9 6h11M9 12h11M9 18h11"/><circle cx="5" cy="6" r="1"/><circle cx="5" cy="12" r="1"/><circle cx="5" cy="18" r="1"/>',trash:'<path d="M4 7h16M9 7V4h6v3m-9 0 1 14h10l1-14"/>',power:'<path d="M12 3v9"/><path d="M7 5.7a8 8 0 1 0 10 0"/>',play:'<path d="m8 5 11 7-11 7V5Z"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="1"/>',upload:'<path d="M12 21V9m-4 4 4-4 4 4M5 4h14"/>',
