const icon=(n:string,x='')=>`<svg class="icon ${x}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.info}</svg>`;
const brandMark=()=>`<span class="brand-mark brand-mark-controller" aria-hidden="true"><svg viewBox="0 0 40 32" fill="none"><path d="M8.4 10.2C10.8 7.5 14.1 6 20 6s9.2 1.5 11.6 4.2c2.2 2.5 3.5 7.6 2.2 11.2-.9 2.6-2.8 4.6-5.1 4.6-2.5 0-3.7-2.8-5.2-4.4h-7c-1.5 1.6-2.7 4.4-5.2 4.4-2.3 0-4.2-2-5.1-4.6-1.3-3.6 0-8.7 2.2-11.2Z" fill="currentColor" opacity=".22" stroke="currentColor" stroke-width="1.6"/><path d="M12 15v6m-3-3h6M27 16h.01M30 20h.01" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg></span>`;
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));const tr=(k:string,v?:Record<string,string|number>)=>esc(t(k,v));const fmt=(v:number)=>new Intl.NumberFormat(getLocale()).format(v);
function bytes(v:number){if(!Number.isFinite(v)||v<0)return'—';const u=['B','KiB','MiB','GiB','TiB'];const i=Math.min(v?Math.floor(Math.log(v)/Math.log(1024)):0,u.length-1);return`${new Intl.NumberFormat(getLocale(),{maximumFractionDigits:1}).format(v/1024**i)} ${u[i]}`}
function time(v:number){try{return v?new Intl.DateTimeFormat(getLocale(),{dateStyle:'medium',timeStyle:'short'}).format(new Date(v*1000)):'—'}catch{return'—'}}
function technical(raw:string){return raw?`<details class="technical-evidence"><summary>${icon('code')}<span>${tr('diagnostics.technicalEvidence')}</span></summary><pre>${esc(raw)}</pre></details>`:''}
const sessionFailureMessages:Record<string,string>={steam_session_offline:'error.steamSessionOffline',steam_session_signed_out:'error.steamSessionSignedOut',steam_session_identity_changed:'error.steamSessionChanged',steam_session_startup_timeout:'error.steamSessionStarting',steam_client_invalid:'error.steamClientInvalid'};
function failure(e:unknown):UIFailure{if(typeof e==='object'&&e){const r=e as Record<string,unknown>,code=typeof r.code==='string'?r.code:undefined;const a=typeof r.messageArgs==='object'&&r.messageArgs?Object.fromEntries(Object.entries(r.messageArgs).filter((x):x is[string,string]=>typeof x[1]==='string')):undefined;return{code,messageKey:code&&sessionFailureMessages[code]|| (typeof r.messageKey==='string'?r.messageKey:undefined),messageArgs:a,detail:typeof r.detail==='string'?r.detail:e instanceof Error?e.message:JSON.stringify(e)}}return{detail:String(e)}}
function invalidateAchievementState(tab:NonNullable<typeof achievementTabs.active>,reason:UIFailure,global=false){
 tab.error=reason;tab.warning=null;tab.selection.clear();
 if(tab.catalog)tab.catalog={...tab.catalog,writable:false,connected:global?false:tab.catalog.connected,error:null,sessionErrorCode:global?reason.code:null,achievements:tab.catalog.achievements.map(item=>({...item,unlocked:null,unlockTime:null}))};
}
function invalidateSteamSession(reason:UIFailure){
 for(const tab of achievementTabs.all){++tab.request;tab.loading=false;invalidateAchievementState(tab,reason,true)}
 clearCurrentSessionState(reason);
 render();
}

function failureHtml(f:UIFailure){return`<p class="failure-message">${esc(localizedMessage(f.messageKey,f.messageArgs,'app.errorHelp'))}</p>${technical(f.detail)}`}
const badge=(l:string,k='neutral')=>`<span class="badge ${esc(k)}"><span class="status-dot"></span>${esc(l)}</span>`;const button=(l:string,a:string,g='',s='secondary',x='')=>`<button class="button ${s}" data-action="${a}" ${state.busy?'disabled':''} ${x}>${g?icon(g):''}<span>${tr(l)}</span></button>`;
function pathField(id:string,v:string,p:string,a:string){return`<div class="path-field">${icon('folder')}<input id="${id}" type="text" value="${esc(v)}" placeholder="${tr(p)}" title="${esc(v)}"><button class="icon-button" data-action="${a}">${icon('folder')}</button></div>`}
function empty(title:string,desc:string,g='info',action=''){return`<div class="empty-state"><span class="empty-icon">${icon(g)}</span><h3>${tr(title)}</h3><p>${tr(desc)}</p>${action}</div>`}
function metric(l:string,v:string,n:string,g:string){return`<article class="metric"><div class="metric-label">${icon(g)}${tr(l)}</div><div class="metric-value">${esc(v)}</div><div class="metric-note">${esc(n)}</div></article>`}
function allDiagnostics():Diagnostic[]{return[...(state.kernelInstallation?.diagnostics||[]),...(state.snapshot?.warnings||[]).map((detail,i)=>({code:`steam.warning.${i}`,severity:'warning' as const,title:t('diagnostics.steamWarning'),detail}))]}
function diagRow(d:Diagnostic){const s=['error','warning','success','info'].includes(d.severity)?d.severity:'info';const k=`diagnostic.${d.code}.title`;return`<article class="diagnostic-item ${s}"><span class="diagnostic-icon">${icon(s==='success'?'check':s==='info'?'info':'warning')}</span><div class="diagnostic-body"><div class="diagnostic-heading"><h3>${esc(t(k)===k?t('diagnostics.genericTitle'):t(k))}</h3>${badge(t(`status.${s}`),s)}</div><p class="diagnostic-message">${esc(localizedMessage(d.messageKey,d.messageArgs))}</p>${technical(`${d.title}\n${d.detail}`)}<code>${esc(d.code)}</code></div></article>`}
function shell(){
 const pages:Page[]=['kernel','library','import','manifest','extract','achievements','overview','diagnostics','settings'];
 const alerts=allDiagnostics().filter(d=>d.severity==='warning'||d.severity==='error').length;
 const canExport=!!(state.snapshot||state.kernelInstallation);
 return`<div class="app-shell"><aside class="sidebar"><a href="#kernel" class="brand" data-page="kernel">${brandMark()}<span class="brand-name">SteamTools<span>Next<span class="brand-dot">.</span></span></span></a><nav>${pages.map(p=>`<button class="nav-item ${state.page===p?'active':''}" data-page="${p}" aria-label="${tr(`nav.${p}`)}" title="${tr(`nav.${p}`)}">${icon(p)}<span>${tr(`nav.${p}`)}</span>${p==='diagnostics'&&alerts?`<span class="nav-count">${alerts}</span>`:''}${state.page===p?'<span class="nav-active-mark"></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom">${steamAccounts.markup()}<div class="local-pill"><span class="status-dot"></span>${tr('common.localManagement')}</div><span class="version-label">v${esc(state.environment.version)}</span></div></aside><div class="workspace" data-current-page="${state.page}"><header class="topbar"><div class="topbar-title">${icon(state.page)}<h1 title="${tr(`page.${state.page}.description`)}">${tr(`page.${state.page}.title`)}</h1></div><div class="topbar-actions">${button('common.refresh','refresh','refresh')}<button class="language-button" data-action="language" aria-label="${tr('settings.language')}">${icon('globe')}<span>${esc(getLocale())}</span></button><details class="page-options"><summary aria-label="${tr('common.moreOptions')}" title="${tr('common.moreOptions')}">${icon('settings')}</summary><div class="page-options-menu">${updates.menuButton()}${button('common.export','export','export','secondary',canExport?'':'disabled')}${badge(t(state.environment.desktop?'status.local':'status.preview'),state.environment.desktop?'success':'warning')}<small>${state.snapshot?`${tr('status.scanned')} ${esc(time(state.snapshot.capturedAt))}`:tr('status.notScanned')}</small></div></details></div></header>${!state.environment.desktop?`<div class="demo-banner">${icon('info')}<span>${tr('app.demo')}</span></div>`:''}<main>${state.error?`<div class="error-banner" role="alert">${icon('warning')}<div><strong>${tr('app.error')}</strong>${failureHtml(state.error)}</div><button class="icon-button" data-action="dismiss-error">${icon('close')}</button></div>`:''}${state.initialized&&!state.settingsLoaded?`<div class="session-only-banner">${icon('info')}<p>${tr('settings.sessionOnly')}</p></div>`:''}${state.busy?`<div class="progress-strip"><span class="spinner"></span>${tr(state.busy)}<span class="progress-line"></span></div>`:''}<div class="page-content">${renderPage()}</div></main></div></div>${state.toast?`<div class="toast" role="status" aria-live="polite">${icon('check')}<div>${esc(state.toast)}</div><button class="icon-button" data-action="dismiss-toast" aria-label="${tr('common.close')}">${icon('close')}</button></div>`:''}${updates.markup()}`;
}

function renderPage(){if(!state.initialized)return empty('app.initializing','common.loading','refresh');switch(state.page){case'kernel':return kernelPage();case'library':return libraryPage();case'import':return importPage();case'manifest':return manifestPage();case'extract':return extractPage();case'achievements':return achievementsPage();case'overview':return overviewPage();case'diagnostics':return diagnosticsPage();case'settings':return settingsPage()}}
function versionSourceLabel(source:KernelInstallation['versionSource']){return source==='peResource'?t('kernel.versionSourceFile'):source==='artifactManifest'?t('kernel.versionSourceArtifact'):t('kernel.versionSourceUnknown')}
function renderHashEvidence(i:KernelInstallation){const label=i.hashMatch===true?t('kernel.hashMatch.match'):i.hashMatch===false?t('kernel.hashMatch.mismatch'):t('kernel.hashMatch.unknown');const cls=i.hashMatch===true?'evidence-ok':i.hashMatch===false?'evidence-warning':'';return`<span class="${cls}">${icon(i.hashMatch===true?'check':'info')}<span>${tr('kernel.hashMatch')}</span><strong>${esc(label)}</strong></span>`}
function installationPanel(i:KernelInstallation){const kind=i.status==='enabled'?'success':i.status==='conflict'||i.status==='incomplete'?'warning':'neutral';const version=installationVersion(i);return`<div class="installation-summary"><div class="installation-status-block"><span>${tr('kernel.installStatus')}</span><strong>${tr(`kernel.installStatus.${i.status}`)}</strong>${badge(t(`kernel.injectionMethod.${i.injectionMethod}`),kind)}<small>${esc(i.path)}</small></div><div class="installation-facts"><div><span>${tr('kernel.installedVersion')}</span><strong>${esc(version||t('common.unknown'))}</strong><small>${esc(versionSourceLabel(i.versionSource))}</small></div><div><span>${tr('kernel.fileCount')}</span><strong>${fmt(i.files.length)}</strong><small>${tr('kernel.filesDetected',{count:i.files.length})}</small></div><div><span>${tr('kernel.remnants')}</span><strong>${fmt(i.remnants.length)}</strong><small>${i.remnants.length?t('kernel.attention'):t('kernel.remnantsNone')}</small></div><div><span>${tr('kernel.loadedUnverified')}</span><strong>${i.runtimeLoadVerified?t('status.valid'):t('status.runtimeUntested')}</strong><small>${tr('kernel.runtimeDisclaimer')}</small></div></div></div><div class="installation-evidence">${renderHashEvidence(i)}${i.installedSha256?`<span><span>${tr('kernel.installedHash')}</span><code>${esc(shortHash(i.installedSha256))}</code></span>`:''}${i.artifactSha256?`<span><span>${tr('kernel.artifactSha')}</span><code>${esc(shortHash(i.artifactSha256))}</code></span>`:''}</div><details class="installation-details"><summary>${icon('code')}<span>${tr('diagnostics.technicalEvidence')}</span></summary><dl><div><dt>${tr('kernel.installedFile')}</dt><dd class="mono">${esc(i.path+'\\OpenSteamTool.dll')}</dd></div><div><dt>${tr('kernel.versionSourceFile')}</dt><dd>${esc(versionSourceLabel(i.versionSource))}</dd></div><div><dt>${tr('kernel.runtimeDisclaimer')}</dt><dd>${esc(localizedMessage(i.messageKey,{...i.messageArgs,injectionMethod:t(`kernel.injectionMethod.${i.injectionMethod}`)}))}</dd></div></dl></details>${i.remnants.length?`<div class="installation-alert warning"><strong>${tr('kernel.remnants')}</strong><ul>${i.remnants.map(r=>`<li class="mono">${esc(r)}</li>`).join('')}</ul></div>`:''}`}
function shortHash(value:string|null|undefined){return value?`${value.slice(0,8)}…${value.slice(-6)}`:t('common.unknown')}
function installationVersion(i:KernelInstallation){return i.version||(i.hashMatch===true?i.artifactVersion:null)}
function installedKernelPanel(){let content='';if(!state.snapshot?.steam)content=empty('kernel.installedNoSteam','kernel.installedNoSteamDescription','monitor');else if(state.installedError)content=`<div class="inline-notice error">${failureHtml(state.installedError)}</div>`;else if(!state.installedScanComplete)content=`<div class="installed-pending"><span class="spinner"></span>${tr('status.scanning')}</div>`;else if(state.kernelInstallation)content=installationPanel(state.kernelInstallation);else content=empty('kernel.installedAbsent','kernel.installedAbsentDescription','kernel');return`<section class="installed-kernel-panel surface"><div class="section-heading"><div><h2 title="${tr('kernel.installedDescription')}">${tr('kernel.installedTitle')}</h2></div>${icon('monitor')}</div>${content}</section>`}
function kernelManagement(){const steam=state.snapshot?.steam;const release=state.kernelRelease;const installed=state.kernelInstallation;const canInstall=!!steam&&!steam.running;const canUninstall=canInstall&&!!installed&&installed.status!=='notInstalled';return`<section class="surface management-panel"><div class="section-heading"><div><h2>${tr('kernel.managementTitle')}</h2></div>${icon('power')}</div><p class="kernel-release-help">${tr('kernel.installDownloadDescription')}</p>${release?`<div class="artifact-meta"><span>${tr('kernel.artifactVersion')}: <strong>${esc(release.version)}</strong></span><span>${tr(release.cacheHit?'kernel.verifiedCache':'kernel.downloadVerified')}</span></div>`:''}${steam?.running?`<div class="inline-notice warning">${icon('warning')}<p>${tr('kernel.stopSteamFirst')}</p></div>`:''}<div class="management-actions">${button('common.install','kernel-install','upload','primary',canInstall?'':'disabled')}${button('common.uninstall','kernel-uninstall','trash','danger',canUninstall?'':'disabled')}</div></section>`}
function kernelPage(){return`${installedKernelPanel()}${updates.kernelBanner()}${kernelManagement()}`}

function libraryMetadata(e:LuaLibraryEntry){
 const candidates=[
  ...[metadataCache.get(metadataKey(e.appId))].filter((game):game is CatalogGame=>!!game),
  ...state.catalogResults.filter(game=>game.appId===e.appId),
  ...(state.rankings?[...state.rankings.popular,...state.rankings.recommended]:[]).filter(game=>game.appId===e.appId),
  ...(state.snapshot?.apps||[]).filter(app=>app.appid===e.appId).map(app=>({name:app.name,coverUrl:steamCoverUrl(e.appId)})),
 ];
 const match=candidates[0];
 const extra=match&&'coverCandidates'in match&&Array.isArray(match.coverCandidates)?match.coverCandidates as string[]:[];
 return {name:match?.name||`AppID ${e.appId}`,coverUrl:match?.coverUrl||steamCoverUrl(e.appId),coverCandidates:steamCoverCandidates(e.appId,[match?.coverUrl||'',...extra])};
}
function libraryName(e:LuaLibraryEntry){return libraryMetadata(e).name}
function pinnedLabel(e:LuaLibraryEntry){return e.pinnedManifestCount?String(e.pinnedManifestCount)+' '+tr('library.pinnedShort'):tr('library.noPinned')}
function filteredLua(){
 const q=state.libraryQuery.trim().toLowerCase();
 const entries=[...(state.luaLibrary?.entries||[])].filter(e=>(!q||libraryName(e).toLowerCase().includes(q)||String(e.appId).includes(q)||e.appIds.some(id=>String(id).includes(q)))&&(state.libraryFilter==='all'||(state.libraryFilter==='enabled')===e.enabled));
 return entries.sort((a,b)=>{
  if(state.librarySort==='nameDesc')return libraryName(b).localeCompare(libraryName(a),getLocale());
  if(state.librarySort==='appDesc')return b.appId-a.appId;
  if(state.librarySort==='appAsc')return a.appId-b.appId;
  return libraryName(a).localeCompare(libraryName(b),getLocale());
 });
}
function steamCoverUrl(appId:number){return`https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${appId}/header.jpg`}
async function hydrateLibraryMetadata(){
 if(metadataLoading)return;metadataLoading=true;
 const locale=getLocale();
 try{
  const visible=[...root.querySelectorAll<HTMLElement>('[data-game-appid]')].slice(0,20).map(node=>Number(node.dataset.gameAppid));
  const ids=[...new Set([...visible,...[...(state.snapshot?.apps||[])].sort((a,b)=>(b.lastPlayed||0)-(a.lastPlayed||0)).slice(0,10).map(app=>app.appid),...(state.luaLibrary?.entries||[]).map(e=>e.appId)])].filter(id=>id>0&&!metadataCache.has(metadataKey(id,locale)));
  let next=0;
  const worker=async()=>{while(next<ids.length){const appId=ids[next++];try{
   const result=await searchCatalog(String(appId),locale);const match=result.find(game=>game.appId===appId&&game.name&&!/^App(?:ID)?\s*\d+$/i.test(game.name));
   if(match){metadataCache.set(metadataKey(appId,locale),match);if(locale===getLocale())for(const name of root.querySelectorAll<HTMLElement>(`[data-game-appid="${appId}"] [data-game-name]`)){name.textContent=match.name;name.title=match.name}}
  }catch{}}};
  await Promise.all(Array.from({length:Math.min(8,ids.length)},worker));
  try{localStorage.setItem('stn-library-metadata-v2',JSON.stringify([...metadataCache.entries()].slice(-500)))}catch{}
 }finally{metadataLoading=false;if(locale!==getLocale())void hydrateLibraryMetadata()}
}
function cardAction(label:string,action:string,glyph:string,kind=''){return`<button class="icon-button library-card-icon ${kind}" data-action="${action}" title="${tr(label)}" aria-label="${tr(label)}">${icon(glyph)}</button>`}
function libraryCover(e:LuaLibraryEntry,large=false){
 const meta=libraryMetadata(e);
 return state.draftSettings.showCovers?`<div class="${large?'lua-card-cover':'lua-list-cover'}">${coverImage(e.appId,meta.coverCandidates)}<span class="cover-fallback">${String(e.appId).slice(-2)}</span></div>`:`<span class="${large?'lua-card-cover':'lua-list-cover'} no-cover"><span class="cover-fallback">${String(e.appId).slice(-2)}</span></span>`;
}
function coverImage(appId:number,candidates:string[]){const cached=coverLoader.peek({steamPath:state.snapshot?.steam?.path||null,appId,language:getLocale(),candidates,desktop:state.environment.desktop});return`<img src="${esc(cached?.dataUrl||coverPlaceholder(appId))}" data-cover-appid="${appId}" data-cover-candidates="${esc(JSON.stringify(candidates))}" alt="" decoding="async" data-cover-image>`}
