function manifestPage(){const r=state.manifestResult;return`<section class="surface manifest-control"><div class="manifest-mode"><label class="method-option ${state.manifestMode==='code'?'selected':''}"><input type="radio" name="manifest-mode" value="code" ${state.manifestMode==='code'?'checked':''}><span><strong>${tr('manifest.codeDirect')}</strong><small>${tr('manifest.codeDirectDescription')}</small></span></label><label class="method-option ${state.manifestMode==='manifestHub'?'selected':''}"><input type="radio" name="manifest-mode" value="manifestHub" ${state.manifestMode==='manifestHub'?'checked':''}><span><strong>ManifestHub</strong><small>${tr('manifest.hubDescription')}</small></span></label></div>${state.manifestMode==='manifestHub'?`<label class="field-label" for="manifest-api-key">${tr('manifest.apiKey')}</label><input id="manifest-api-key" class="wide-input" type="password" value="${esc(state.manifestApiKey)}" autocomplete="off">`:''}<div class="management-actions">${button('manifest.pollOnce','manifest-poll','refresh','primary')}${button(state.manifestRunning?'common.stop':'common.start',state.manifestRunning?'manifest-stop':'manifest-start',state.manifestRunning?'stop':'play')}</div></section>${r?`<section class="manifest-stats"><article><strong>${r.poll.requests.length}</strong><span>${tr('manifest.discovered')}</span></article><article><strong>${r.downloaded.length}</strong><span>${tr('manifest.downloaded')}</span></article><article><strong>${r.failed.length}</strong><span>${tr('manifest.failed')}</span></article></section><section class="surface operation-log"><pre>${esc([...r.downloaded.map(x=>`✓ ${x.request.depotId}_${x.request.manifestId} → ${x.destination}`),...r.failed.map(x=>`× ${x.request.depotId}_${x.request.manifestId}: ${x.error}`)].join('\n')||t('manifest.noNewRequests'))}</pre></section>`:`<section class="surface">${empty('manifest.emptyTitle','manifest.emptyDescription','manifest')}</section>`}`}
function extractPage(){
 const stopped=state.snapshot?.steam?.running===false,session=stopped?null:state.currentSession,result=stopped?null:state.sessionExtraction,connected=!!session?.connected,ready=connected&&!state.sessionLoading&&!state.busy;
 const target=Number(state.extractAppId),targetValid=Number.isInteger(target)&&target>0&&target<=4294967295;
 const status=session?.source==='demo'?'extract.previewSession':state.sessionLoading?'extract.connecting':connected?'extract.currentConnected':'extract.currentDisconnected';
 const depotRows=result?.depots.map(depot=>`<tr><td>${depot.depotId}</td><td>${esc(depot.manifestId||'—')}</td><td>${badge(t(depot.keyAvailable?'extract.keyCached':'extract.keyMissing'),depot.keyAvailable?'success':'warning')}</td><td>${esc(depot.keySource||depot.missingReason||'—')}</td></tr>`).join('')||'';
 const resultHtml=result?`<section class="surface extraction-result"><div class="section-heading"><div><h2>${esc(result.appName)}</h2><p>AppID ${result.appId} · ${tr('extract.resultSummary',{depots:result.depots.length,keys:result.keyedDepotCount,assets:result.assets.length})}</p></div>${badge(t(result.complete?'extract.complete':'extract.partial'),result.complete?'success':'warning')}</div>${!result.complete?`<div class="inline-notice warning">${icon('info')}<p>${tr('extract.partialDescription')}</p></div>`:''}<div class="extraction-table-wrap"><table class="extraction-depot-table"><thead><tr><th>DepotID</th><th>ManifestID</th><th>${tr('extract.keyState')}</th><th>${tr('catalog.source')}</th></tr></thead><tbody>${depotRows||`<tr><td colspan="4">${tr('extract.noInstalledDepots')}</td></tr>`}</tbody></table></div>${result.assets.length?`<ul class="extraction-assets">${result.assets.map(asset=>`<li><code>${esc(asset.filename)}</code><span>${bytes(asset.sizeBytes)}</span></li>`).join('')}</ul>`:''}${result.warnings.length?`<details class="extraction-warnings"><summary>${tr('extract.details')}</summary><pre>${esc(result.warnings.join('\n'))}</pre></details>`:''}<details class="extraction-lua-preview"><summary>${tr('extract.luaPreview')}</summary><pre>${esc(result.lua)}</pre></details><div class="management-actions">${button('extract.exportBundle','session-export','export','primary',ready?'':'disabled')}</div></section>`:'';
 return`<section class="surface current-session-panel"><div class="section-heading"><div><h2 title="${tr('extract.currentDescription')}">${tr('extract.currentTitle')}</h2></div>${badge(t(status),connected?'success':'warning')}</div><div class="current-session-account"><span>${tr('extract.account')}</span><strong>${esc(session?.accountLabel||t('common.unknown'))}</strong>${button('extract.connectCurrent','session-connect','refresh','secondary',state.sessionLoading||state.busy?'disabled':'')}</div><div class="inline-notice">${icon('info')}<p>${tr('extract.currentScope')}</p></div>${state.sessionError?`<div class="${state.sessionError.code==='steam_session_offline'?'inline-notice warning current-session-unavailable':'error-banner'}" role="${state.sessionError.code==='steam_session_offline'?'status':'alert'}">${failureHtml(state.sessionError)}</div>`:''}${session?.error?`<details class="extraction-warnings"><summary>${tr('extract.details')}</summary><pre>${esc(session.error)}</pre></details>`:''}<div class="current-session-controls"><select id="extract-session-game" aria-label="${tr('extract.selectGame')}" ${ready?'':'disabled'}><option value="">${tr('extract.selectGame')}</option>${(session?.games||[]).map(game=>`<option value="${game.appId}" ${Number(state.extractAppId)===game.appId?'selected':''}>${esc(game.name)} · ${game.appId}</option>`).join('')}</select><input id="session-extract-appid" inputmode="numeric" value="${esc(state.extractAppId)}" placeholder="${tr('extract.appIdPlaceholder')}" ${ready?'':'disabled'}>${button('extract.readCurrent','session-extract','extract','primary',ready&&targetValid?'':'disabled')}</div></section>${resultHtml}${state.extractionExport?`<section class="surface"><h2>${tr('extract.exported')}</h2><code>${esc(state.extractionExport.destinationDirectory)}</code><p>${tr('extract.exportSummary',{count:state.extractionExport.files.length})}</p></section>`:''}<details class="surface extraction-cache-section"><summary>${tr('extract.cacheTitle')}</summary><p>${tr('extract.cacheDescription')}</p><div class="catalog-search-row"><input id="extract-appid" class="wide-input" inputmode="numeric" value="${esc(state.extractAppId)}" placeholder="${tr('extract.appIdPlaceholder')}">${button('extract.generate','extract-generate','extract','primary')}</div>${optionStrip()}</details>${state.catalogLog.length?`<section class="surface operation-log"><pre>${esc(state.catalogLog.join('\n'))}</pre></section>`:''}`;
}

