 root.querySelectorAll<HTMLElement>('[data-action]').forEach(e=>e.addEventListener('click',()=>{const a=e.dataset.action||'';if(a==='refresh')void refresh();else if(a==='browse-steam')void browseSteam();else if(a==='export')void operation('status.exporting',async()=>{showToast(t('app.exported',{path:await exportReport(state.snapshot,state.kernelInstallation)}));});else if(a==='language')changePage('settings');else if(a==='save-settings')void savePreferences();else if(a==='kernel-install')void manageKernel('install');else if(a==='kernel-uninstall')void manageKernel('uninstall');else if(a==='library-import')void importFiles();else if(a==='library-add-basic')void addBasic();else if(a==='catalog-search')void searchGames();else if(a==='catalog-refresh-keys')void operation('status.importing',async()=>{const r=await refreshKeyCache();showToast(t('catalog.keysUpdated',{size:bytes(r.depotKeysBytes+r.appTokensBytes)}));});else if(a==='extract-generate'){const id=Number(state.extractAppId);if(Number.isInteger(id)&&id>0)void addCatalogGame(id)}else if(a==='session-connect')void refresh();else if(a==='session-extract')void readCurrentSessionGame();else if(a==='session-export')void exportCurrentSessionBundle();else if(a==='achievement-unlock-all')void applyAchievementChange(true,'all');else if(a==='achievement-lock-all')void applyAchievementChange(false,'all');else if(a==='achievement-unlock-selected')void applyAchievementChange(true,'selected');else if(a==='achievement-lock-selected')void applyAchievementChange(false,'selected');else if(a==='achievement-reset')resetAchievementChange();else if(a==='achievement-reload')void loadSelectedAchievements();else if(a==='achievement-select-visible')toggleVisibleAchievements();else if(a.startsWith('achievement-unlock:'))void applyAchievementChange(true,{id:decodeURIComponent(a.slice('achievement-unlock:'.length))});else if(a.startsWith('achievement-lock:'))void applyAchievementChange(false,{id:decodeURIComponent(a.slice('achievement-lock:'.length))});else if(a==='achievements-refresh')void refresh();else if(a.startsWith('achievement-select:'))selectAchievementGame(Number(a.split(':')[1]));else if(a==='manifest-poll')void operation('status.polling',manifestTick);else if(a==='manifest-start')startManifest();else if(a==='manifest-stop')stopManifest();else if(a==='dismiss-error'){state.error=null;render()}else if(a==='dismiss-toast'){state.toast='';if(toastTimer){window.clearTimeout(toastTimer);toastTimer=0}render()}else if(a.startsWith('copy-appid:'))void copyAppId(Number(a.split(':')[1]));else if(a.startsWith('lua-enable:'))void mutateLua('enable',Number(a.split(':')[1]));else if(a.startsWith('lua-disable:'))void mutateLua('disable',Number(a.split(':')[1]));else if(a.startsWith('lua-delete:'))void mutateLua('delete',Number(a.split(':')[1]));else if(a.startsWith('catalog-add:'))void addCatalogGame(Number(a.split(':')[1]))}));
 const inputs:Record<string,(v:string)=>void>={'settings-steam-path':v=>state.draftSettings.steamPath=v||null,'library-query':v=>state.libraryQuery=v,'basic-appid':v=>state.basicAppId=v,'catalog-query':v=>state.catalogQuery=v,'extract-appid':v=>state.extractAppId=v,'session-extract-appid':v=>{state.extractAppId=v;state.sessionExtraction=null;state.extractionExport=null},'achievement-query':v=>state.achievementQuery=v,'achievement-detail-query':v=>state.achievementDetailQuery=v,'manifest-api-key':v=>state.manifestApiKey=v};for(const[id,cb]of Object.entries(inputs))document.getElementById(id)?.addEventListener('input',ev=>{cb((ev.target as HTMLInputElement).value);if(!isComposing.has(id)&&(id==='library-query'||id==='achievement-query'||id==='achievement-detail-query'||id==='session-extract-appid'))render()});root.querySelectorAll<HTMLInputElement>('input').forEach(f=>{f.addEventListener('compositionstart',()=>isComposing.add(f.id));f.addEventListener('compositionend',()=>{isComposing.delete(f.id);if(pendingRender)render()})});
