 const bools:[string,'includeDlc'|'pinManifest'|'fetchNameComments'|'autoRefreshKeyCache'|'showRanking'|'autoRefreshLibrary'|'enableLogging'|'compactMode'|'showCovers'|'reduceMotion'][]=[['catalog-include-dlc','includeDlc'],['catalog-pin-manifest','pinManifest'],['catalog-fetch-names','fetchNameComments'],['autoRefreshKeyCache','autoRefreshKeyCache'],['showRanking','showRanking'],['autoRefreshLibrary','autoRefreshLibrary'],['enableLogging','enableLogging'],['compactMode','compactMode'],['showCovers','showCovers'],['reduceMotion','reduceMotion']];for(const[id,key]of bools)document.getElementById(id)?.addEventListener('change',e=>{setBoolean(key,(e.target as HTMLInputElement).checked);render()});document.getElementById('accent-color')?.addEventListener('change',e=>void saveAppearance({accentColor:(e.target as HTMLSelectElement).value as Settings['accentColor']}));document.getElementById('settings-download-mode')?.addEventListener('change',e=>{state.draftSettings.downloadMode=(e.target as HTMLSelectElement).value as Settings['downloadMode'];render()})
