async function initialize(){const p=location.hash.slice(1);if(['kernel','library','import','manifest','extract','achievements','overview','diagnostics','settings'].includes(p))state.page=p as Page;render();try{const[env,saved]=await Promise.allSettled([getEnvironment(),loadSettings()]);if(env.status==='fulfilled')state.environment=env.value;state.settingsLoaded=saved.status==='fulfilled';if(saved.status==='fulfilled'){state.persistedSettings=migrateKernelSettings({...defaultSettings,...saved.value},state.environment.defaultKernelReleaseSource||DEFAULT_KERNEL_RELEASE_SOURCE);state.draftSettings={...state.persistedSettings}}setLocale(state.persistedSettings.language==='auto'?state.environment.locale:state.persistedSettings.language);state.initialized=true;if(saved.status==='rejected')throw saved.reason;state.busy='status.scanning';await scanWorkspace();if(state.page==='import'&&state.draftSettings.showRanking)state.rankings=await loadCatalogRankings().catch(()=>null)}catch(e){state.error=failure(e)}finally{state.initialized=true;state.busy='';render();if(state.page==='library'||state.page==='achievements')void hydrateLibraryMetadata();if(state.page==='extract')void loadCurrentSession();void updates.check(true)}}
